RiskSettingsPage::~RiskSettingsPage(){try{persist();}catch(...) {}}
void RiskSettingsPage::load(QJsonObject record){baseline=riskSettings::validateRecord(record);filling=true;for(auto it=fields.begin();it!=fields.end();++it){auto value=QJsonDocument(QJsonArray{record.value("thresholds").toObject().value(it.key())}).toJson(QJsonDocument::Compact);it.value()->setText(QString::fromUtf8(value.mid(1,value.size()-2)));}filling=false;dirty=false;}
QJsonObject RiskSettingsPage::thresholds()const{QJsonObject out;for(auto it=fields.begin();it!=fields.end();++it){bool ok;double value=it.value()->text().trimmed().toDouble(&ok);riskSettings::need(ok,"风险阈值须为数字，草稿未改为默认");out[it.key()]=value;}return riskSettings::validateThresholds(out);}
void RiskSettingsPage::refresh(){evaluation={};list->clear();counts->setText("输入尚未可用，未评估");scope->setText("等待读取当前持仓与行情");riskSettings::need(bool(inputs),"未接只读本地风险输入，未生成固定提醒");const auto in=inputs();for(auto k:{"accounts","trades","quoteInstruments","watchlistInstruments"})riskSettings::need(in.value(k).isArray(),QString("只读输入缺少")+k);riskSettings::need(in.value("leaderConfig").isObject(),"只读输入缺少人工龙头配置");QJsonObject account;{QSignalBlocker block(accounts);accounts->clear();accounts->addItem("请选择账户（持仓未评估）","");for(auto v:in.value("accounts").toArray()){const auto r=v.toObject();accounts->addItem((r.value("type")=="paper"?"模拟账本 · ":"")+r.value("name").toString()+" · "+r.value("id").toString(),r.value("id").toString());if(r.value("id").toString()==accountId)account=r;}int index=accounts->findData(accountId);accounts->setCurrentIndex(std::max(0,index));}auto snap=riskSettings::snapshot(account,in.value("trades").toArray(),in.value("quoteInstruments").toArray(),in.value("watchlistInstruments").toArray(),in.value("leaderConfig").toObject(),in.value("capturedAt").toString(),in.value("sourceLabel").toString());auto saved=store->read();evaluation=riskSettings::evaluate(saved.value("thresholds").toObject(),snap);auto t=saved.value("thresholds").toObject();active->setText(QString("生效：浮盈亏 %1% · 日涨跌 ±%2% · 龙头下跌 %3%；草稿保存后生效\n设置版本 %4 · 保存时间 %5").arg(t.value("drawdown").toDouble()).arg(t.value("dailyDrop").toDouble()).arg(t.value("leaderDrop").toDouble()).arg(saved.value("revision").toDouble()).arg(saved.value("updatedAt").toString("默认设置，尚未保存")));scope->setText("账户："+(account.isEmpty()?QString("未选择 / 原账户已不存在"):account.value("name").toString())+" · "+accountId+"\n输入："+snap.value("sourceLabel").toString()+" · 读取时点 "+snap.value("capturedAt").toString()+"（非行情实时性证明）；浮盈亏率并非峰值回撤。");page=0;render();}
