void RiskSettingsPage::save(bool reset){auto next=store->save(reset?riskSettings::defaults():thresholds(),baseline);load(next);refresh();persist();if(changed)changed();status->setText(reset?"默认值已生效并重算；不修改持仓、行情或止损点位":"设置已保存并用当前本地快照重算");persist();}
