void RiskSettingsPage::previewImport(const QByteArray& bytes){pending={};pendingBaseline={};persist();auto next=riskSettings::decode(bytes);pending=next;pendingBaseline=store->read();selectedAlert={};original->setPlainText("设置导入预览：确认后替换当前生效阈值；原编辑草稿仍保留\n"+QString::fromUtf8(QJsonDocument(next).toJson(QJsonDocument::Indented)));views->setCurrentIndex(1);status->setText("导入预览，尚未写入或改变提醒；请复核旧值默认化说明");persist();}
void RiskSettingsPage::confirmImport(){riskSettings::need(!pending.isEmpty(),"没有待确认设置");auto next=store->save(pending.value("thresholds").toObject(),pendingBaseline,pending.value("legacyOriginal"),pending.value("importWarnings").toArray());pending={};pendingBaseline={};if(!dirty)load(next);refresh();persist();if(changed)changed();views->setCurrentIndex(0);status->setText(dirty?"导入已生效；原编辑草稿保留，继续保存须显式重读":"导入已生效并重算");persist();}
void RiskSettingsPage::cancelImport(){pending={};pendingBaseline={};back();status->setText("已取消导入；当前设置和原草稿未改变");persist();}
bool RiskSettingsPage::back(){if(views->currentIndex()!=1)return false;views->setCurrentIndex(0);return true;}
void RiskSettingsPage::setAccount(QString id){accountId=std::move(id);guard([this]{refresh();persist();});}
QString RiskSettingsPage::statePath()const{return store->filePath()+".risk-settings-view.json";}
QJsonObject RiskSettingsPage::state()const{QJsonObject values;for(auto it=fields.begin();it!=fields.end();++it)values[it.key()]=it.value()->text();return {{"schema","risk-settings-view/v1"},{"baseline",baseline},{"values",values},{"dirty",dirty},{"accountId",accountId},{"severity",severity->currentIndex()},{"query",search->text()},{"pending",pending},{"pendingBaseline",pendingBaseline}};}
void RiskSettingsPage::persist()const{riskSettings::need(stateWritable,"草稿读取失败，原状态未覆盖；请显式重读或放弃后接管");auto bytes=riskSettings::json(state());riskSettings::need(bytes.size()<=4*1024*1024,"设置草稿超过4MiB，原状态未覆盖");QSaveFile f(statePath());riskSettings::need(f.open(QIODevice::WriteOnly)&&f.write(bytes)==bytes.size()&&f.commit(),"设置草稿未能落盘，原状态未覆盖");}
QJsonObject RiskSettingsPage::saveState()const{persist();return {{"stateFile",statePath()}};}
void RiskSettingsPage::restoreState(const QJsonObject& marker){riskSettings::need(marker.value("stateFile").toString()==statePath(),"不是此风险设置文件的草稿");restore();refresh();}
void RiskSettingsPage::restore(){QFile f(statePath());if(!f.exists())return;stateWritable=false;riskSettings::need(f.open(QIODevice::ReadOnly)&&f.size()<=4*1024*1024,"设置草稿不可读或过大，未清空");auto d=QJsonDocument::fromJson(f.readAll());riskSettings::need(d.isObject()&&d.object().value("schema")=="risk-settings-view/v1","设置草稿损坏，未清空");const auto r=d.object();riskSettings::validateRecord(r.value("baseline").toObject());for(auto it=fields.begin();it!=fields.end();++it)riskSettings::need(r.value("values").toObject().value(it.key()).isString()&&r.value("values").toObject().value(it.key()).toString().size()<=it.value()->maxLength(),"设置草稿字段缺失或无法完整恢复");riskSettings::need(r.value("dirty").isBool()&&r.value("accountId").isString()&&r.value("query").isString()&&r.value("pending").isObject()&&r.value("pendingBaseline").isObject(),"设置草稿结构不完整");load(r.value("baseline").toObject());filling=true;for(auto it=fields.begin();it!=fields.end();++it){riskSettings::need(r.value("values").toObject().value(it.key()).isString(),"设置草稿字段缺失");it.value()->setText(r.value("values").toObject().value(it.key()).toString());}filling=false;dirty=r.value("dirty").toBool();accountId=r.value("accountId").toString();severity->setCurrentIndex(r.value("severity").toInt());search->setText(r.value("query").toString());pending=r.value("pending").toObject();pendingBaseline=r.value("pendingBaseline").toObject();if(!pending.isEmpty()){selectedAlert={};original->setPlainText("恢复的设置导入预览，尚未写入；原草稿保留\n"+QString::fromUtf8(QJsonDocument(pending).toJson(QJsonDocument::Indented)));views->setCurrentIndex(1);}stateWritable=true;status->setText("设置草稿已恢复；保留原完整基线，过期保存将拒绝");}
